mapper.select:
select insitituteCode, customerName, termStr, mdate, Credit_Amt/100000000 as Credit_Amt, credit_type, '同业' as customerType, HAP_CREDIT_AMT/100000000 as HAP_CREDIT_AMT from (SELECT ROW_NUMBER() over(PARTITION by t.customer_id, t.CREDIT_MST_ID ORDER BY t.PFLSH DESC) as rn, t.* from (
SELECT T1.PFLSH, T2.CUSTOMER_NAME customerName, T1.CUSTOMER_ID, T1.CREDIT_MST_ID, T2.INSITITUTE_CODE insitituteCode, T3.TERM || decode(T3.term_unit, 'D', '天', 'W', '周', 'M', '月', 'Y', '年', '年') as termStr, T3.credit_type as credit_type, T1.mdate, T1.Credit_Amt, T1.HAP_CREDIT_AMT FROM credit_lines T1 left join (select T.CUSTOMER_ID, INFO.CUSTOMER_NAME, T.INSITITUTE_CODE from MST_CUSTOMER_INFO_ADD t left join MST_CUSTOMER_INFO info on t.customer_id = info.customer_id where 1 = 1) T2 on T2.CUSTOMER_ID = T1.CUSTOMER_ID left join (select info.credit_mst_id, tag.credit_type, info.term, info.term_unit, dict1.item_value termUnit from credit_conf_info info left join credit_tag_info tag on info.credit_tag_id = tag.credit_tag_id left join sys_datadict_list dict1 on dict1.dict_code = 'TERM_UNIT' and info.TERM_UNIT = dict1.item_code where 1 = 1 ) T3 on T3.credit_mst_id = T1.credit_mst_id left join sys_datadict_list dict2 on dict2.dict_code = 'LIMIT_TYPE' and dict2.item_code = T3.credit_type where 1 = 1 and T1.Vdate >= #{cdate,jdbcType=DATE} and dict2.item_value like '%同业ABS%' ) t
) where rn = 1

select insitituteCode, customerName, termStr, mdate, Credit_Amt/100000000 as Credit_Amt, credit_type, appro_id, finprod_name as assetName, Busi_Type, '同业' as customerType, HAP_CREDIT_AMT/100000000 as HAP_CREDIT_AMT from (SELECT ROW_NUMBER() over(PARTITION by t.customer_id, t.CREDIT_MST_ID ORDER BY t.PFLSH DESC) as rn, t.* from (
SELECT T1.PFLSH, T2.CUSTOMER_NAME customerName, T1.CUSTOMER_ID, T1.CREDIT_MST_ID, T2.INSITITUTE_CODE insitituteCode, T3.TERM || decode(T3.term_unit, 'D', '天', 'W', '周', 'M', '月', 'Y', '年', '年') as termStr, T3.credit_type as credit_type, T1.mdate, prod.finprod_name, T3.appro_id, T3.Busi_Type, T1.Credit_Amt, T1.HAP_CREDIT_AMT FROM credit_lines T1 left join (select T.CUSTOMER_ID, INFO.CUSTOMER_NAME, T.INSITITUTE_CODE from MST_CUSTOMER_INFO_ADD t left join MST_CUSTOMER_INFO info on t.customer_id = info.customer_id where 1 = 1) T2 on T2.CUSTOMER_ID = T1.CUSTOMER_ID left join (select info.credit_mst_id, tag.credit_type, tag.appro_id, tag.busi_type, info.term, info.term_unit, dict1.item_value termUnit from credit_conf_info info left join credit_tag_info tag on info.credit_tag_id = tag.credit_tag_id left join sys_datadict_list dict1 on dict1.dict_code = 'TERM_UNIT' and info.TERM_UNIT = dict1.item_code where 1 = 1 ) T3 on T3.credit_mst_id = T1.credit_mst_id left join sys_datadict_list dict2 on dict2.dict_code = 'LIMIT_TYPE' and dict2.item_code = T3.credit_type left join Fin_Product prod on prod.finprod_id = T3.APPRO_ID where 1 = 1 and T1.Vdate >= #{cdate,jdbcType=DATE} and T3.Appro_Id is not null and T3.Busi_Type is not null) t
) where rn = 1

select insitituteCode, customerName, termStr, mdate, Credit_Amt/100000000 as Credit_Amt, credit_type, '同业' as customerType, HAP_CREDIT_AMT/100000000 as HAP_CREDIT_AMT from (SELECT ROW_NUMBER() over(PARTITION by t.customer_id, t.CREDIT_MST_ID ORDER BY t.PFLSH DESC) as rn, t.* from (
SELECT T1.PFLSH, T2.CUSTOMER_NAME customerName, T1.CUSTOMER_ID, T1.CREDIT_MST_ID, T2.INSITITUTE_CODE insitituteCode, T3.TERM || decode(T3.term_unit, 'D', '天', 'W', '周', 'M', '月', 'Y', '年', '年') as termStr, T3.credit_type as credit_type, T1.mdate, T1.Credit_Amt, T1.HAP_CREDIT_AMT FROM credit_lines T1 left join (select T.CUSTOMER_ID, INFO.CUSTOMER_NAME, T.INSITITUTE_CODE from MST_CUSTOMER_INFO_ADD t left join MST_CUSTOMER_INFO info on t.customer_id = info.customer_id where 1 = 1) T2 on T2.CUSTOMER_ID = T1.CUSTOMER_ID left join (select info.credit_mst_id, tag.credit_type, info.term, info.term_unit, dict1.item_value termUnit from credit_conf_info info left join credit_tag_info tag on info.credit_tag_id = tag.credit_tag_id left join sys_datadict_list dict1 on dict1.dict_code = 'TERM_UNIT' and info.TERM_UNIT = dict1.item_code where 1 = 1 ) T3 on T3.credit_mst_id = T1.credit_mst_id left join sys_datadict_list dict2 on dict2.dict_code = 'LIMIT_TYPE' and dict2.item_code = T3.credit_type where 1 = 1 and T1.Vdate >= #{cdate,jdbcType=DATE} and T3.org_type in ('01', '03')) t
) where rn = 1
